<?php

declare(strict_types=1);

namespace Patchlevel\Hydrator\Extension\Generated;

use Patchlevel\Hydrator\Extension;
use Patchlevel\Hydrator\StackHydratorBuilder;

/**
 * Uses the mappers generated by the {@see GeneratedMapperWarmer}. Classes without a generated mapper
 * are mapped with reflection.
 */
final class GeneratedMapperExtension implements Extension
{
    /** @param string $cachePath Directory where the {@see GeneratedMapperWarmer} stored the generated code. */
    public function __construct(
        private readonly string $cachePath,
    ) {
    }

    public function configure(StackHydratorBuilder $builder): void
    {
        $builder->addMapperFactory(new GeneratedMapperFactory(new MapperFiles($this->cachePath)));
    }
}
